  }

  async next(deps: WorkflowDeps): Promise<WorkflowEffect> {
    if (!this.active) return { kind: "idle", phase: this.phase };
    return this.advancePhase(deps);
  }

  async end(deps: WorkflowDeps): Promise<WorkflowEffect> {
