   100	    const statePath = resolve(base, entry.name, WORKFLOW_STATE_FILENAME);
   101	    try {
   102	      const run = await loadWorkflowRun(statePath, modes);
   103	      if (run.status === "active") listed.push({ statePath, run });
   104	    } catch {
   105	      // A corrupt or unrelated artifact is not a resumable run.
   106	    }
   107	  }
   108	  return listed.sort((a, b) => b.run.updatedAt.localeCompare(a.run.updatedAt));
   109	}
