   111	export async function resolveWorkflowRun(selector: string, base: string, modes: WorkflowModes): Promise<ListedWorkflowRun> {
   112	  const root = resolve(base);
   113	  const candidate = resolve(root, selector);
   114	  if (selector.includes("/") || selector.includes("\\") || selector.endsWith(".json") || selector.startsWith(".")) {
   115	    if (!isInside(root, candidate)) throw new Error("Workflow run path must be inside the artifacts directory.");
   116	    const statePath = candidate.endsWith(WORKFLOW_STATE_FILENAME) ? candidate : resolve(candidate, WORKFLOW_STATE_FILENAME);
   117	    const run = await loadWorkflowRun(statePath, modes);
   118	    return { statePath, run };
   119	  }
   120	  const runs = await listResumableWorkflowRuns(root, modes);
   121	  const found = runs.find(({ run }) => run.id === selector);
   122	  if (!found) throw new Error(`No resumable workflow run with id ${selector}.`);
   123	  return found;
   124	}

